// Stage 2: Multi-Dimensional Scoring & Top-K Sifting
// Groups surviving pairs by user_id and selects Top 3 highest-scoring products
const items = $input.all();
const userMap = {};

for (const item of items) {
  const row = item.json;
  const uid = row.user_id;
  if (!userMap[uid]) {
    userMap[uid] = {
      user: {
        user_id: uid,
        name: row.name,
        email: row.email,
        monthly_income: parseFloat(row.monthly_income),
        credit_score: parseInt(row.credit_score),
        employment_status: row.employment_status,
        age: parseInt(row.age)
      },
      candidates: []
    };
  }

  const minIncome = parseFloat(row.min_income);
  const minScore = parseInt(row.min_credit_score);
  const minRate = parseFloat(row.interest_rate_min);
  const income = userMap[uid].user.monthly_income;
  const score = userMap[uid].user.credit_score;
  const emp = userMap[uid].user.employment_status;

  // 1. Credit Headroom (35%)
  const creditHeadroom = Math.max(0, score - minScore);
  const creditComp = Math.min(35.0, (creditHeadroom / Math.max(1, 850 - minScore)) * 35.0);

  // 2. Income Surplus (30%)
  const incomeRatio = income / Math.max(1, minIncome);
  const incomeComp = Math.min(30.0, (incomeRatio / 2.0) * 30.0);

  // 3. Rate Appeal (20%)
  const rateComp = Math.max(5.0, Math.min(20.0, 20.0 - (minRate - 9.0) * 2.5));

  // 4. Employment Stability (15%)
  const empComp = emp === 'Salaried' ? 15.0 : 13.5;

  const totalScore = Math.min(100.0, Math.max(10.0, Math.round((creditComp + incomeComp + rateComp + empComp) * 100) / 100));
  const reasons = [
    `Credit score ${score} exceeds threshold of ${minScore} (+${creditHeadroom} pts)`,
    `Monthly income ₹${income.toLocaleString()} provides ${incomeRatio.toFixed(1)}x coverage over minimum ₹${minIncome.toLocaleString()}`,
    `Annualized starting rate at ${minRate.toFixed(2)}% p.a.`,
    `Employment category '${emp}' verified under prime lending guidelines`
  ];

  userMap[uid].candidates.push({
    product_id: row.product_id,
    product_name: row.product_name,
    bank_name: row.bank_name,
    interest_rate_min: minRate,
    max_loan_amount: parseFloat(row.max_loan_amount),
    score: totalScore,
    reasons: reasons
  });
}

const output = [];
for (const uid in userMap) {
  const userObj = userMap[uid];
  userObj.candidates.sort((a, b) => b.score - a.score);
  const top3 = userObj.candidates.slice(0, 3);

  // Stage 3: Synthesize qualitative advice for the user profile
  const bestProd = top3[0];
  const scoreVal = userObj.user.credit_score;
  const incomeVal = userObj.user.monthly_income;
  let advice = '';
  if (scoreVal >= 750) {
    advice = `Exceptional credit standing (${scoreVal}) places you in the Tier-1 borrower category. ${bestProd.product_name} offers the lowest APR with maximum loan headroom. Leverage your high credit tier for zero processing fee waivers.`;
  } else {
    advice = `Strong financial profile meeting all solvency criteria. ${bestProd.product_name} provides the most competitive interest terms at ${bestProd.interest_rate_min}% p.a.`;
  }

  for (const m of top3) {
    output.push({
      json: {
        user_id: uid,
        product_id: m.product_id,
        eligibility_score: m.score,
        match_reasons: JSON.stringify(m.reasons),
        ai_recommendation: advice,
        user_name: userObj.user.name,
        user_email: userObj.user.email
      }
    });
  }
}

return output;

